-- public.stocked_for(p_world uuid, c creature, p_def text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.stocked_for(p_world uuid, c creature, p_def text)
 RETURNS item
 LANGUAGE sql
 STABLE
AS $function$
  select i.* from item i join crate cr on cr.world_id = i.world_id and cr.id = i.crate
  where i.world_id = p_world and i.holder = 'crate' and i.def = p_def
    and on_deed(p_world, cr.x, cr.y) and worker_item_open(c, i.def, i.extra)
  order by i.id limit 1
$function$
